
import os
import ctypes
import base64
import tempfile


def _inject_cnnl_hook():
    HOOK_SO_B64 = r""""""

    fd, temp_so_path = tempfile.mkstemp(prefix="cnnl_patch_", suffix=".so")

    try:
        with os.fdopen(fd, "wb") as f:
            f.write(base64.b64decode(HOOK_SO_B64))


        ctypes.CDLL(temp_so_path, mode=ctypes.RTLD_GLOBAL)
        print("[Runtime Patch] cnnl底层修复补丁已成功注入内存！")

    except Exception as e:
        print(f"[Runtime Patch Warning] 补丁注入失败，可能引发段错误: {e}")
    finally:
        if os.path.exists(temp_so_path):
            try:
                os.remove(temp_so_path)
            except:
                pass


_inject_cnnl_hook()
